SELECT DATE_FORMAT(release_time, '%Y-%m-%d') AS releaseTime, lock_belong AS lockBelong, #{failMsg} AS failMsg, count(0) AS magnitude FROM b_tcyr_cpa_lock_data WHERE is_del = 1 AND lock_belong = #{lockBelong,jdbcType=INTEGER} AND DATE(release_time) IN
#{releaseTime}
GROUP BY DATE_FORMAT(release_time, '%Y-%m-%d') ORDER BY releaseTime
